A possible fix would be to add this code in `index.js`, after [https://github.com/WordPress/WordPress/blob/c67763478840fabf689ecbd175dc682da1623069/wp-content/themes/twentytwenty/assets/js/index.js#L156 line 156]:


{{{
goToAnchor: function() {
	document.addEventListener( 'click', function( event ) {
		var target = event.target;

		if ( target.closest( '.modal-menu' ) && 'a' === target.tagName.toLowerCase() ) {
