		<?php echo esc_html( $label ); ?>
	</option>
<?php endforeach; ?>
}}}

This will allow:

{{{
function me_filter_gallery_settings( $settings ) {
	$settings['galleryDefaults']['size'] = 'large';
	return $settings;
